import { useState } from "react";
import { useNavigate } from "react-router-dom";

const menuData = [
  {
    category: "Cocktails",
    items: [
      { name: "Mojito", price: 7.5, available: true },
      { name: "Caipirinha", price: 7.0, available: true },
      { name: "Sex on the Beach", price: 8.0, available: true },
    ],
  },
  {
    category: "Snacks",
    items: [
      { name: "Pommes", price: 4.0, available: true },
      { name: "Nachos mit Käse", price: 5.5, available: true },
    ],
  },
];

export default function CustomerPage() {
  const [cart, setCart] = useState([]);
  const [tableNumber, setTableNumber] = useState("");
  const navigate = useNavigate();

  const addToCart = (item) => {
    setCart([...cart, item]);
  };

  const total = cart.reduce((sum, item) => sum + item.price, 0);

  const handleOrder = () => {
    if (!tableNumber) return alert("Bitte Tischnummer eingeben.");
    const order = {
      items: cart,
      tableNumber,
      status: "Ausstehend",
      timestamp: Date.now(),
    };
    localStorage.setItem("currentOrder", JSON.stringify(order));
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    localStorage.setItem("allOrders", JSON.stringify([...allOrders, order]));
    navigate("/status");
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white p-4">
      <h1 className="text-2xl font-bold mb-4">Speisekarte</h1>
      {menuData.map((cat, i) => (
        <div key={i} className="mb-6">
          <h2 className="text-xl font-semibold mb-2">{cat.category}</h2>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {cat.items.map((item, idx) => (
              <button
                key={idx}
                disabled={!item.available}
                onClick={() => addToCart(item)}
                className={`p-3 rounded border text-left ${
                  item.available
                    ? "bg-blue-600 hover:bg-blue-700"
                    : "bg-gray-500 cursor-not-allowed"
                }`}
              >
                {item.name} – {item.price.toFixed(2)} €
              </button>
            ))}
          </div>
        </div>
      ))}

      <div className="mt-6">
        <h2 className="text-xl font-semibold mb-2">Warenkorb</h2>
        {cart.length === 0 ? (
          <p>🛒 Dein Warenkorb ist leer.</p>
        ) : (
          <ul className="list-disc pl-5">
            {cart.map((item, index) => (
              <li key={index}>
                {item.name} – {item.price.toFixed(2)} €
              </li>
            ))}
          </ul>
        )}

        <p className="mt-4 font-bold">Gesamtpreis: {total.toFixed(2)} €</p>

        <input
          className="mt-4 p-2 w-full md:w-1/2 rounded text-black"
          placeholder="Tischnummer"
          value={tableNumber}
          onChange={(e) => setTableNumber(e.target.value)}
        />

        <button
          onClick={handleOrder}
          disabled={cart.length === 0}
          className="mt-4 bg-green-600 hover:bg-green-700 px-6 py-2 rounded"
        >
          Bestellung abschicken
        </button>
      </div>
    </div>
  );
}
